from pathlib import Path
import csv
import re
from datetime import datetime

infile = Path('/work/data/data.csv')
outdir = Path('/out/artifacts')
outdir.mkdir(parents=True, exist_ok=True)
outfile = outdir / 'standardized_data.csv'

# Read CSV as raw strings
with infile.open('r', encoding='utf-8-sig', newline='') as f:
    reader = csv.DictReader(f)
    rows = list(reader)
    fieldnames = reader.fieldnames or []

# Clean helper functions
currency_re = re.compile(r'[\$\€\£\¥\,，\s]')
percent_re = re.compile(r'\s*%\s*$')

uk_markers = {'united kingdom', 'u.k.', 'uk', 'great britain', 'britain'}
us_markers = {'usa', 'u.s.a.', 'united states', 'us', 'u.s.'}


def parse_number(val):
    if val is None:
        return None
    s = str(val).strip()
    if s == '':
        return None
    neg = False
    if s.startswith('(') and s.endswith(')'):
        neg = True
        s = s[1:-1].strip()
    is_pct = bool(percent_re.search(s))
    s = percent_re.sub('', s)
    s = currency_re.sub('', s)
    # keep only digits, decimal point, minus sign
    s = re.sub(r'[^0-9.\-]', '', s)
    if s in {'', '-', '.', '-.'}:
        return None
    try:
        num = float(s)
        if neg:
            num = -num
        if is_pct:
            num /= 100.0
        return num
    except ValueError:
        return val


def parse_date(date_val, country_val=None):
    if date_val is None:
        return None
    s = str(date_val).strip()
    if not s:
        return None

    country = (country_val or '').strip().lower()
    dayfirst = country in uk_markers

    # Try a small set of explicit formats first.
    formats = [
        '%Y-%m-%d',
        '%Y/%m/%d',
        '%Y.%m.%d',
        '%Y%m%d',
        '%m/%d/%Y' if not dayfirst else '%d/%m/%Y',
        '%d/%m/%Y' if not dayfirst else '%m/%d/%Y',
        '%m-%d-%Y' if not dayfirst else '%d-%m-%Y',
        '%d-%m-%Y' if not dayfirst else '%m-%d-%Y',
        '%Y年%m月%d日',
    ]
    for fmt in formats:
        try:
            return datetime.strptime(s, fmt).strftime('%Y-%m-%d')
        except ValueError:
            pass

    # Fallback to pandas-like flexible parsing via datetime.fromisoformat/dateutil unavailable.
    # Handle ambiguous slash dates using country-specific dayfirst.
    try:
        parts = re.split(r'[/-]', s)
        if len(parts) == 3 and all(p.isdigit() for p in parts):
            a, b, c = map(int, parts)
            if len(parts[0]) == 4:
                return datetime(a, b, c).strftime('%Y-%m-%d')
            if dayfirst:
                return datetime(c, b, a).strftime('%Y-%m-%d')
            return datetime(c, a, b).strftime('%Y-%m-%d')
    except Exception:
        pass

    return s

cleaned = []
for row in rows:
    new_row = dict(row)
    # strip whitespace in all fields
    for k, v in new_row.items():
        if isinstance(v, str):
            new_row[k] = v.strip()

    if 'amount' in new_row:
        amt = parse_number(new_row['amount'])
        new_row['amount'] = '' if amt is None else f'{amt:.2f}'

    if 'order_date' in new_row:
        new_row['order_date'] = parse_date(new_row['order_date'], new_row.get('country')) or ''

    cleaned.append(new_row)

# Write cleaned CSV
with outfile.open('w', encoding='utf-8', newline='') as f:
    writer = csv.DictWriter(f, fieldnames=fieldnames)
    writer.writeheader()
    writer.writerows(cleaned)

print(outfile)
