10	Call soffice through run_soffice, not through subprocess with get_soffice_env():
11	the env dict carries the shim but names no user profile, and a non-root sandbox
12	cannot bootstrap the default one -- soffice aborts with "User installation could
13	not be completed" and converts nothing. get_soffice_env() stays public for the
14	callers that build their own argv (they must pass -env:UserInstallation too).
15	"""
16	
17	import contextlib
18	import os
19	import socket
20	import subprocess
21	import tempfile
22	from collections.abc import Iterable
23	from pathlib import Path
24	
25	
26	def get_soffice_env() -> dict:
27	    env = os.environ.copy()
28	    env["SAL_USE_VCLPLUGIN"] = "svp"
29	
30	    if _needs_shim():
31	        shim = _ensure_shim()
32	        env["LD_PRELOAD"] = str(shim)
33	
34	    return env
