37	def run_soffice(args: Iterable[str], **kwargs) -> subprocess.CompletedProcess:
38	    args = list(args)
39	    with contextlib.ExitStack() as stack:
40	        if not any(str(a).startswith("-env:UserInstallation") for a in args):
41	            profile = stack.enter_context(
42	                tempfile.TemporaryDirectory(prefix="lo_profile_", ignore_cleanup_errors=True)
43	            )
44	            args = [f"-env:UserInstallation={Path(profile).as_uri()}"] + args
45	        return subprocess.run(["soffice"] + args, env=get_soffice_env(), **kwargs)
