88	static int (*real_socketpair)(int, int, int, int[2]);
89	static int (*real_listen)(int, int);
90	static int (*real_accept)(int, struct sockaddr *, socklen_t *);
91	static int (*real_close)(int);
92	static int (*real_read)(int, void *, size_t);
