94	/* Per-FD bookkeeping (FDs >= 1024 are passed through unshimmed). */
95	static int is_shimmed[1024];
96	static int peer_of[1024];
97	static int wake_r[1024];            /* accept() blocks reading this */
98	static int wake_w[1024];            /* close()  writes to this      */
99	static int listener_fd = -1;        /* FD that received listen()    */
100	
101	__attribute__((constructor))
102	static void init(void) {
103	    real_socket     = dlsym(RTLD_NEXT, "socket");
104	    real_socketpair = dlsym(RTLD_NEXT, "socketpair");
105	    real_listen     = dlsym(RTLD_NEXT, "listen");
106	    real_accept     = dlsym(RTLD_NEXT, "accept");
107	    real_close      = dlsym(RTLD_NEXT, "close");
108	    real_read       = dlsym(RTLD_NEXT, "read");
109	    for (int i = 0; i < 1024; i++) {
110	        peer_of[i] = -1;
111	        wake_r[i]  = -1;
112	        wake_w[i]  = -1;
113	    }
114	}
115	
116	/* ---- socket ---------------------------------------------------------- */
117	int socket(int domain, int type, int protocol) {
118	    if (domain == AF_UNIX) {
119	        int fd = real_socket(domain, type, protocol);
120	        if (fd >= 0) return fd;
121	        /* socket(AF_UNIX) blocked – fall back to socketpair(). */
122	        int sv[2];
123	        if (real_socketpair(domain, type, protocol, sv) == 0) {
124	            if (sv[0] >= 0 && sv[0] < 1024) {
125	                is_shimmed[sv[0]] = 1;
126	                peer_of[sv[0]]    = sv[1];
127	                int wp[2];
128	                if (pipe(wp) == 0) {
129	                    wake_r[sv[0]] = wp[0];
130	                    wake_w[sv[0]] = wp[1];
131	                }
132	            }
133	            return sv[0];
134	        }
135	        errno = EPERM;
136	        return -1;
137	    }
138	    return real_socket(domain, type, protocol);
139	}
