174	            wake_w[fd] = -1;
175	        }
176	        if (wake_r[fd] >= 0) { real_close(wake_r[fd]); wake_r[fd]  = -1; }
177	        if (peer_of[fd] >= 0) { real_close(peer_of[fd]); peer_of[fd] = -1; }
